<?php declare(strict_types=1);namespace App\Command;use App\Imperium\Runtime\Senate\SubordinatePersonaFindingAuthorityOpeningService;use Symfony\Component\Console\Attribute\AsCommand;use Symfony\Component\Console\Command\Command;use Symfony\Component\Console\Input\InputArgument;use Symfony\Component\Console\Input\InputInterface;use Symfony\Component\Console\Output\OutputInterface;#[AsCommand(name:'imperium:senate:open-subordinate-persona-finding-authorities')]final class SenateOpenSubordinatePersonaFindingAuthoritiesCommand extends Command{public function __construct(private readonly SubordinatePersonaFindingAuthorityOpeningService$s){parent::__construct();}protected function configure():void{$this->addArgument('required-trial-ledger-id',InputArgument::REQUIRED);}protected function execute(InputInterface$i,OutputInterface$o):int{try{$r=$this->s->open((string)$i->getArgument('required-trial-ledger-id'));}catch(\Throwable$e){$o->writeln('<error>REFUSED</error> '.$e->getMessage());return self::FAILURE;}$o->writeln('<info>SENATOR_FINDING_AUTHORITIES_OPEN_PENDING_SEPARATE_FINDINGS</info> '.$r['authority_set_id']);return self::SUCCESS;}}
